# Arkusze CKE z historii w trybie „link + omówienie”:
# materiały źródłowe zostają w oryginalnym PDF-ie CKE (link do właściwej strony),
# a w aplikacji są tylko: skrót polecenia, wzorcowa odpowiedź opracowana na podstawie
# zasad oceniania CKE, krótka zasada punktowania i omówienie IndexLab.
CKE = 'https://cke.gov.pl/images/_EGZAMIN_MATURALNY_OD_2023/Arkusze_egzaminacyjne'


def W(nr, strona, tytul, dzial, *zadania):
    return {'nr': nr, 'strona': strona, 'tytul': tytul,
            'zadania': [dict(z, dzialy=[dzial]) for z in zadania]}


def Z(nr, pkt, polecenie, odpowiedz, omowienie, zasady=None):
    if zasady is None:
        zasady = '1 pkt – odpowiedź poprawna (przy rozstrzygnięciu: z uzasadnieniem odwołującym się do źródeł).\n0 pkt – odpowiedź niepoprawna lub niepełna.' if pkt == 1 else ''
    return {'nr': nr, 'punkty': pkt, 'polecenie': polecenie, 'odpowiedz': odpowiedz, 'zasady': zasady, 'omowienie': omowienie}


